from mk import *
from lib import mini
import math
G = 6.67e-11; M = 5.98e24; R = 6.37e6
v = math.sqrt(G * M / (R + 1.9e5))
clip = lambda y: max(-1, min(1, y))
F2 = lambda x: clip(0.012 / (x + 0.08) ** 2 - 0.0016 / (1.04 - x) ** 2 * 0.9)

def fig():
    g = Fig(640, 400, "למעלה: כדור הארץ, המרכז, נקודה D על הקו לירח, המרחק rE ממרכז כדור הארץ ל-D, והמרחק rM מ-D למרכז הירח. למטה: ארבעה גרפים של שקול כוחות הכבידה כפונקציה של המרחק r ממרכז כדור הארץ. גרף 1: קבוע וחיובי ואז קפיצה לשלילי. גרף 2: יורד מערך חיובי גדול ליד כדור הארץ, חוצה את האפס, ושואף לערך שלילי גדול ליד הירח. גרף 3: קו ישר יורד. גרף 4: יורד מערך חיובי גדול לערך שלילי קטן וקבוע כמעט")
    ex, ey, mx = 110, 95, 560
    g.circle(ex, ey, 60, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(ex, ey - 70, "כדור הארץ")
    g.circle(mx, ey, 16, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(mx, ey - 26, "הירח")
    g.dot(ex, ey); g.dot(mx, ey); g.line(ex, ey, mx, ey, width=1.1, dash="5 4")
    dx = 250; g.ball(dx, ey, r=5); g.text(dx, ey - 12, "D")
    g.dim(ex, ey + 26, dx, ey + 26, "rE", ext=False, label_dy=6); g.dim(dx, ey + 26, mx, ey + 26, "rM", ext=False, label_dy=6)
    defs = [("1", dict(segs=[[(0.02, 0.7), (0.78, 0.7), (0.78, -0.18), (0.95, -0.18)]])),
            ("2", dict(fn=None, segs=[(F2, 0.0, 1.0)])),
            ("3", dict(pts=[(0.0, 0.9), (1.0, -0.9)])),
            ("4", dict(segs=[(lambda x: clip(0.01 / (x + 0.06) ** 2 - 0.25), 0.0, 1.0)]))]
    for i, (lab, kw) in enumerate(defs):
        mini(g, 490 - i * 150, 290, 110, 60, label=lab, xl="r", yl="ΣF", neg=True, **kw)
    return g

E(id="bagrut-2019-q6", year=2019, label="2019 שאלה 6", topic="gravitation", sub="grav-law", diff=3, fig=fig,
  stem=r"ביולי 1969 במשימת אפולו 11 נשלחה חללית אל הירח. בדרכה הוכנסה החללית ל\"מסלול ביניים\" מעגלי סביב כדור הארץ, ובו היא נעה כמו לוויין. ממסלול הביניים המשיכה החללית אל הירח. במהלך משימה זו נחתו לראשונה אנשים על פני הירח. הנח כי מסת החללית היא $m$ וגובה מסלול הביניים מעל פני כדור הארץ הוא $h = 190\,\text{km}$. בסעיפים א-ג הנח כי רק כדור הארץ משפיע על החללית. נתונים: מסת כדור הארץ $5.98 \times 10^{24}\,\text{kg}$, רדיוס כדור הארץ $6.37 \times 10^6\,\text{m}$.",
  parts=[
    P("א", r"חשב את גודל המהירות של החללית במסלול הביניים.", num(v, "m/s", tol=1), ["principle", "algebra"], [
        S(r"כבידה ככוח צנטריפטלי", r"$r = R + h = 6.56 \times 10^6\,\text{m}$", r"v = \sqrt{\frac{GM}{R + h}} = \sqrt{\frac{6.67 \times 10^{-11} \cdot 5.98 \times 10^{24}}{6.56 \times 10^6}} \approx 7.8 \times 10^3\,\text{m/s}"),
    ], r"$v \approx 7.8 \times 10^3\,\text{m/s}$", key=r"v=7788 m/s"),
    P("ב", r"תלמידה טוענת כי על פי החוק הראשון של ניוטון, במסלול הביניים החללית נמצאת במצב של שיווי משקל, מאחר שהיא נעה במהירות שגודלה קבוע. קבע אם התלמידה צודקת ונמק את קביעתך.", choice(["צודקת", "לא צודקת"], 1), ["principle"], [
        S(r"המהירות היא וקטור", r"גודלה קבוע, אבל כיוונה משתנה כל הזמן", r"\vec{a} = \frac{v^2}{r} \ne 0"),
        S(r"החוק הראשון", r"שיווי משקל רק כשווקטור המהירות קבוע", r"\sum \vec{F} = \frac{GMm}{r^2} \ne 0"),
    ], r"לא צודקת: כיוון המהירות משתנה, ולכן יש שקול כוחות", key=r"velocity is a vector"),
    P("ג1", r"אילו הייתה לחללית הנעה במסלול הביניים הנתון מסה גדולה יותר, האם גודל המהירות של החללית היה גדל, קטן או לא משתנה? נמק.", choice(["גדל", "קטן", "לא משתנה"], 2), ["principle"], [
        S(r"המסה מצטמצמת", r"מהחוק השני", r"v = \sqrt{\frac{GM_E}{R_E + h}}"),
    ], r"לא משתנה", key=r"v=√(GME/(RE+h))"),
    P("ג2", r"אילו הייתה לחללית מסה גדולה יותר, האם האנרגיה המכנית הכוללת שלה הייתה גדלה, קטנה או לא משתנה? (שים לב לסימן של האנרגיה.)", choice(["גדלה", "קטנה", "לא משתנה"], 1), ["principle", "signs"], [
        S(r"אנרגיה כוללת במסלול", r"שלילית ופרופורציונלית למסה", r"E = -\frac{GMm}{2r}"),
        S(r"מסה גדולה יותר", r"ערך מוחלט גדול יותר של מספר שלילי", r"m \uparrow \Rightarrow E \downarrow"),
    ], r"קטנה (נעשית שלילית יותר)", key=r"E=−GMm/2r"),
    P("ד", r"הנח כי החללית המשיכה ממסלול הביניים למסלול סביב הירח לאורך קו ישר המחבר את מרכז כדור הארץ למרכז הירח. הנקודה $D$ נמצאת על ישר זה (ראה תרשים). בסעיפים ד-ה הנח כי רק כדור הארץ והירח משפיעים על החללית. בטא את שקול כוחות הכבידה הפועלים על החללית, $\sum F_G$, בנקודה $D$, באמצעות $M_E$, $M_M$, $r_E$, $r_M$, $G$, $m$.", OPEN, ["fbd", "signs"], [
        S(r"שני כוחות בכיוונים מנוגדים", r"כדור הארץ מושך לכיוונו, הירח לכיוונו. חיובי: כלפי כדור הארץ", r"\sum F_G = \frac{GM_E m}{r_E^2} - \frac{GM_M m}{r_M^2}"),
    ], r"$\sum F_G = \frac{GM_E m}{r_E^2} - \frac{GM_M m}{r_M^2}$ (חיובי: לכיוון כדור הארץ)", key=r"ΣFG = GMEm/rE² − GMMm/rM²"),
    P("ה", r"לפניך ארבעה גרפים המייצגים באופן מקורב את שקול כוחות הכבידה, $\sum F_G$, כפונקציה של מרחק החללית ממרכז כדור הארץ, $r$. קבע איזה מן הגרפים 1-4 מתאר נכון את שקול כוחות הכבידה הפועלים על החללית במהלך תנועתה ממסלול הביניים אל הירח.", choice(["1", "2", "3", "4"], 1), ["graph", "principle"], [
        S(r"ליד כדור הארץ", r"הכוח של כדור הארץ גדול מאוד", r"r \to R_E:\ \sum F_G \gg 0"),
        S(r"ליד הירח", r"הכוח של הירח גובר, והשקול שלילי וגדל בערכו", r"r_M \to 0:\ \sum F_G \ll 0"),
        S(r"באמצע", r"השקול משתנה ברציפות וחוצה את האפס בנקודה אחת", r"\sum F_G(r_0) = 0"),
    ], r"גרף 2", key=r"graph 2 correct"),
  ],
  concepts=["מהירות במסלול", "החוק הראשון של ניוטון", "אנרגיה במסלול", "שקול כוחות כבידה"],
  summary=r"אפולו 11: מהירות במסלול הביניים, למה אין שיווי משקל, ושקול כוחות הכבידה של כדור הארץ והירח לאורך הדרך.")
